#!/usr/bin/env bash
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/../lib/common.sh"

N="${N:-27}"
[[ "$N" == 27 ]] || { echo 'profiled bucket build-only shim targets n=27' >&2; exit 2; }
PROFILE_FILE="${PROFILE_FILE:-$ONEESAN_ROOT/work/b300_hbm_profile_refined21.env}"
[[ -f "$PROFILE_FILE" ]] || { echo "missing profile file: $PROFILE_FILE" >&2; exit 2; }
# shellcheck disable=SC1090
source "$PROFILE_FILE"

ARCH="${ARCH:-native}"; PM_ACCUM="${PM_ACCUM:-1}"; REBUILD="${REBUILD:-1}"
THREADS="${BUCKET_THREADS:-256}"
WARP_PRECTX_COMPACT="${WARP_PRECTX_COMPACT:-0}"
ORBIT_PRECTX_COMPACT="${ORBIT_PRECTX_COMPACT:-0}"; ORBIT_PRECTX_FLAT_BID="${ORBIT_PRECTX_FLAT_BID:-0}"; ORBIT_PRECTX_FLAT_BID_FUSED="${ORBIT_PRECTX_FLAT_BID_FUSED:-0}"; ORBIT_PRECTX_WARPCOOP="${ORBIT_PRECTX_WARPCOOP:-0}"
ORBITCTA_FLAT="${ORBITCTA_FLAT:-0}"; ORBITCTA_FLAT_CHUNK="${ORBITCTA_FLAT_CHUNK:-1}"; ORBITCTA_FLAT_DYNAMIC="${ORBITCTA_FLAT_DYNAMIC:-0}"; ORBITCTA_FLAT_DYNAMIC_BATCH="${ORBITCTA_FLAT_DYNAMIC_BATCH:-1}"; ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP="${ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP:-0}"; ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES="${ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2="${ORBITCTA_FLAT_DYNAMIC_PIPE2:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP="${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WORKER_WEIGHT="${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WORKER_WEIGHT:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS="${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP="${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP:-0}"; ORBITCTA_FLAT_BLOCKS_PER_SM="${ORBITCTA_FLAT_BLOCKS_PER_SM:-0}"
ORBIT_QUAD_MLP="${ORBIT_QUAD_MLP:-0}"; ORBIT_QUAD_OVERLAP_LOCAL="${ORBIT_QUAD_OVERLAP_LOCAL:-0}"; ORBIT_QUAD_LOCAL_DIRECT_MAX="${ORBIT_QUAD_LOCAL_DIRECT_MAX:-0}"; ORBIT_QUAD_SPARSE_DESC_MLP="${ORBIT_QUAD_SPARSE_DESC_MLP:-0}"; ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0="${ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0:-0}"; ORBIT_QUAD_CPASYNC_PREFETCH_BYTES="${ORBIT_QUAD_CPASYNC_PREFETCH_BYTES:-0}"; ORBIT_QUAD_CPASYNC_GROUP_COLS="${ORBIT_QUAD_CPASYNC_GROUP_COLS:-1}"
PREFIX="${PREFIX:-$ONEESAN_ROOT/work/b300_profiled_buckets_build_n27}"; LOGDIR="${LOGDIR:-${PREFIX}_logs}"; OUT_ENV="${OUT_ENV:-${PREFIX}.env}"
mkdir -p "$LOGDIR" "$(dirname "$OUT_ENV")"
[[ "$REBUILD" == 0 || "$REBUILD" == 1 ]] || { echo 'REBUILD must be 0 or 1' >&2; exit 2; }
command -v nvcc >/dev/null || { echo 'nvcc required' >&2; exit 2; }
command -v nvidia-smi >/dev/null || { echo 'nvidia-smi required' >&2; exit 2; }
(( $(nvidia-smi --query-gpu=index --format=csv,noheader | wc -l) >= 8 )) || { echo 'need 8 visible GPUs' >&2; exit 2; }

need(){ local n="$1"; [[ -n "${!n+x}" ]] || { echo "profile missing $n" >&2; exit 2; }; }
for n in WARP_PROFILE WARP_COL_ILP WARP_SPARSE64 WARP_SORTED WARP_CPASYNC_PAIR WARP_CPASYNC_LOCAL_PAIR WARP_CPASYNC_OVERLAP_LOCAL_PAIR WARP_QUAD_MLP WARP_PRECTX_FORWARD WARP_PRECTX_REVERSE ORBIT_PROFILE ORBIT_COL_ILP ORBIT_SPARSE64 ORBIT_SORTED ORBIT_CPASYNC_PAIR ORBIT_CPASYNC_LOCAL_PAIR ORBIT_CPASYNC_OVERLAP_LOCAL_PAIR ORBIT_PRECTX_FORWARD ORBIT_PRECTX_REVERSE; do need "$n"; done
[[ "$WARP_PROFILE" =~ ^[A-Za-z0-9_.-]+$ && "$ORBIT_PROFILE" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo 'unsafe profile name' >&2; exit 2; }
case "$WARP_COL_ILP" in 2|4);;*)echo "bad WARP_COL_ILP=$WARP_COL_ILP" >&2;exit 2;;esac
case "$ORBIT_COL_ILP" in 2|4);;*)echo "bad ORBIT_COL_ILP=$ORBIT_COL_ILP" >&2;exit 2;;esac
case "$ORBITCTA_FLAT_CHUNK" in 1|2|4|8|16|32);;*)echo 'bad ORBITCTA_FLAT_CHUNK' >&2;exit 2;;esac
case "$ORBITCTA_FLAT_DYNAMIC_BATCH" in 1|2|4|8|16);;*)echo 'bad ORBITCTA_FLAT_DYNAMIC_BATCH' >&2;exit 2;;esac
case "$ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES" in 0|1|2|4);;*)echo 'bad ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES' >&2;exit 2;;esac
case "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WORKER_WEIGHT" in 0|1|2|3|4);;*)echo 'bad producer worker weight' >&2;exit 2;;esac
[[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS" =~ ^[0-9]+$ ]] || { echo 'bad producer adaptive cols' >&2; exit 2; }
case "$ORBIT_QUAD_CPASYNC_PREFETCH_BYTES" in 0|64|128|256);;*)echo 'bad quad prefetch bytes' >&2;exit 2;;esac
case "$ORBIT_QUAD_CPASYNC_GROUP_COLS" in 1|2|4);;*)echo 'bad quad group cols' >&2;exit 2;;esac
[[ "$ORBITCTA_FLAT_BLOCKS_PER_SM" =~ ^[0-9]+$ ]] || { echo 'bad blocks-per-sm' >&2; exit 2; }

if (( WARP_CPASYNC_PAIR || ORBIT_CPASYNC_PAIR )); then
  ARCH="$ARCH" NGPU=8 THREADS="$THREADS" bash "$ONEESAN_ROOT/scripts/bench/b300-cpasync-remote-peer-microprobe.sh" >"$LOGDIR/cpasync-peer.out" 2>"$LOGDIR/cpasync-peer.err"
  grep -q 'cp_async_remote_peer=OK exact=OK' "$LOGDIR/cpasync-peer.out" || { cat "$LOGDIR/cpasync-peer.out" >&2; exit 4; }
fi
if (( WARP_PRECTX_COMPACT || ORBIT_PRECTX_COMPACT )); then ARCH="$ARCH" PM_ACCUM="$PM_ACCUM" bash "$ONEESAN_ROOT/scripts/bench/compact-prectx-selftest.sh" >"$LOGDIR/compact-prectx.out" 2>"$LOGDIR/compact-prectx.err"; fi
if [[ "$ORBIT_QUAD_MLP" == 1 ]]; then bash "$ONEESAN_ROOT/scripts/bench/directgather64-quad-proof.sh" >"$LOGDIR/orbit-quad-proof.out" 2>"$LOGDIR/orbit-quad-proof.err"; fi

WARP_BIN="$ONEESAN_BUILD_DIR/b300_profiled_warp_${WARP_PROFILE}_n27"
ORBIT_BIN="$ONEESAN_BUILD_DIR/b300_profiled_orbit_${ORBIT_PROFILE}_flat${ORBITCTA_FLAT}_chunk${ORBITCTA_FLAT_CHUNK}_dyn${ORBITCTA_FLAT_DYNAMIC}_db${ORBITCTA_FLAT_DYNAMIC_BATCH}_df${ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP}_daw${ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES}_dp${ORBITCTA_FLAT_DYNAMIC_PIPE2}_dpw${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP}_pww${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WORKER_WEIGHT}_pac${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS}_ppw${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP}_psm${ORBITCTA_FLAT_BLOCKS_PER_SM}_bid${ORBIT_PRECTX_FLAT_BID}_bf${ORBIT_PRECTX_FLAT_BID_FUSED}_wc${ORBIT_PRECTX_WARPCOOP}_quad${ORBIT_QUAD_MLP}_qol${ORBIT_QUAD_OVERLAP_LOCAL}_qld${ORBIT_QUAD_LOCAL_DIRECT_MAX}_qsd${ORBIT_QUAD_SPARSE_DESC_MLP}_ql0${ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0}_qgc${ORBIT_QUAD_CPASYNC_GROUP_COLS}_qpf${ORBIT_QUAD_CPASYNC_PREFETCH_BYTES}_n27"

if [[ "$REBUILD" == 1 || ! -x "$WARP_BIN" ]]; then
  N=27 ARCH="$ARCH" OUT="$WARP_BIN" COL_ILP="$WARP_COL_ILP" PM_ACCUM="$PM_ACCUM" DEPTHMAJOR=1 PAIR_MLP=1 MLP_WINDOW4=1 DIRECTGATHER64=1 DIRECTGATHER_SPARSE64="$WARP_SPARSE64" SORTED="$WARP_SORTED" QUAD_MLP="$WARP_QUAD_MLP" CPASYNC_PAIR="$WARP_CPASYNC_PAIR" CPASYNC_LOCAL_PAIR="$WARP_CPASYNC_LOCAL_PAIR" CPASYNC_OVERLAP_LOCAL_PAIR="$WARP_CPASYNC_OVERLAP_LOCAL_PAIR" PRECTX_FORWARD="$WARP_PRECTX_FORWARD" PRECTX_REVERSE="$WARP_PRECTX_REVERSE" PRECTX_COMPACT="$WARP_PRECTX_COMPACT" FORCE7=0 PREFETCH_NEXT=0 PTXAS_VERBOSE=1 TRANSPOSE_MODE=pipeline \
    bash "$ONEESAN_ROOT/scripts/build/b300-directgather-colilp-fast.sh" >"$LOGDIR/warp.build.out" 2>"$LOGDIR/warp.build.err"
fi
if [[ "$REBUILD" == 1 || ! -x "$ORBIT_BIN" ]]; then
  ORBIT_BUILD="$ONEESAN_ROOT/scripts/build/b300-directgather-orbitcta.sh"
  [[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP" == 1 ]] && ORBIT_BUILD="$ONEESAN_ROOT/scripts/build/b300-directgather-orbitcta-pipe2-producer-warp.sh"
  N=27 ARCH="$ARCH" OUT="$ORBIT_BIN" DIRECTGATHER64=1 DIRECTGATHER_SPARSE64="$ORBIT_SPARSE64" DIRECTGATHER_SORT_RANKS=0 ORBITCTA_COL_ILP="$ORBIT_COL_ILP" ORBITCTA_FLAT="$ORBITCTA_FLAT" ORBITCTA_FLAT_CHUNK="$ORBITCTA_FLAT_CHUNK" ORBITCTA_FLAT_DYNAMIC="$ORBITCTA_FLAT_DYNAMIC" ORBITCTA_FLAT_DYNAMIC_BATCH="$ORBITCTA_FLAT_DYNAMIC_BATCH" ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP="$ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP" ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES="$ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES" ORBITCTA_FLAT_DYNAMIC_PIPE2="$ORBITCTA_FLAT_DYNAMIC_PIPE2" PRODUCER_WORKER_WEIGHT="$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WORKER_WEIGHT" PRODUCER_ADAPTIVE_COLS="$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS" PRODUCER_PRECTX_WARPCOOP="$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP" PAIR_MLP=1 CPASYNC_PAIR="$ORBIT_CPASYNC_PAIR" QUAD_MLP="$ORBIT_QUAD_MLP" QUAD_OVERLAP_LOCAL="$ORBIT_QUAD_OVERLAP_LOCAL" QUAD_LOCAL_DIRECT_MAX="$ORBIT_QUAD_LOCAL_DIRECT_MAX" QUAD_SPARSE_DESC_MLP="$ORBIT_QUAD_SPARSE_DESC_MLP" QUAD_OVERLAP_BYPASS_LOCAL0="$ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0" QUAD_CPASYNC_PREFETCH_BYTES="$ORBIT_QUAD_CPASYNC_PREFETCH_BYTES" QUAD_CPASYNC_GROUP_COLS="$ORBIT_QUAD_CPASYNC_GROUP_COLS" PRECTX_FORWARD="$ORBIT_PRECTX_FORWARD" PRECTX_REVERSE="$ORBIT_PRECTX_REVERSE" PRECTX_COMPACT="$ORBIT_PRECTX_COMPACT" PRECTX_WARPCOOP="$ORBIT_PRECTX_WARPCOOP" PRECTX_FLAT_BID="$ORBIT_PRECTX_FLAT_BID" PRECTX_FLAT_BID_FUSED="$ORBIT_PRECTX_FLAT_BID_FUSED" RANKFORMULA_MLP_WINDOW4=1 PM_ACCUM="$PM_ACCUM" PTXAS_VERBOSE=1 \
    bash "$ORBIT_BUILD" >"$LOGDIR/orbit.build.out" 2>"$LOGDIR/orbit.build.err"
  grep -q "flat_dynamic=$ORBITCTA_FLAT_DYNAMIC flat_dynamic_batch=$ORBITCTA_FLAT_DYNAMIC_BATCH flat_dynamic_fuse_lease_prep=$ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP flat_dynamic_adaptive_waves=$ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES flat_dynamic_pipe2=$ORBITCTA_FLAT_DYNAMIC_PIPE2" "$LOGDIR/orbit.build.err" || { echo 'orbit dynamic build marker mismatch' >&2; exit 5; }
  if [[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP" == 1 ]]; then grep -q "pipe2_producer_warp=1 pipe2_producer_worker_weight=$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WORKER_WEIGHT pipe2_producer_adaptive_cols=$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS pipe2_producer_prectx_warpcoop=$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP" "$LOGDIR/orbit.build.err" || { echo 'orbit producer build marker mismatch' >&2; exit 5; }; fi
fi
[[ -x "$WARP_BIN" && -x "$ORBIT_BIN" ]] || { echo 'profiled bucket build missing binary' >&2; exit 5; }

PROFILE_SHA="$(sha256sum "$PROFILE_FILE" | awk '{print $1}')"
{
  printf 'B300_PROFILED_BUCKETS_BUILD_ONLY=1\n'
  printf 'PROFILE_SHA256=%s\n' "$PROFILE_SHA"
  printf 'WARP_PROFILE=%q\n' "$WARP_PROFILE"
  printf 'WARP_BIN=%q\n' "$WARP_BIN"
  printf 'ORBIT_PROFILE=%q\n' "$ORBIT_PROFILE"
  printf 'ORBIT_BIN=%q\n' "$ORBIT_BIN"
} >"$OUT_ENV"
cat "$OUT_ENV"
echo "b300-profiled-buckets-only OK env=$OUT_ENV producer_adaptive_cols=$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_ADAPTIVE_COLS" >&2
